<?php
declare(strict_types=1);
$pageTitle='Contact Church Office';require_once __DIR__.'/../includes/header.php';require_once __DIR__.'/_helpers.php';require_permission('member.profile.view');
$uid=(int)($_SESSION['user_id']??0);$mid=current_member_id();if(empty($_SESSION['member_contact_csrf']))$_SESSION['member_contact_csrf']=bin2hex(random_bytes(32));$csrf=(string)$_SESSION['member_contact_csrf'];
$allowedRoles=['admin'=>'Administrator','secretary'=>'Secretary','treasurer'=>'Treasurer'];$recipients=[];
if(mp_table($conn,'users')){$rows=mp_rows($conn,"SELECT id,full_name,email,LOWER(TRIM(role)) role FROM users WHERE LOWER(TRIM(role)) IN ('admin','secretary','treasurer') AND email IS NOT NULL AND TRIM(email)<>'' AND (status IS NULL OR LOWER(status) IN ('active','1','enabled')) ORDER BY role,full_name");foreach($rows as $r){$role=(string)$r['role'];if(isset($allowedRoles[$role]))$recipients[]=$r;}}
$flash=$_SESSION['member_contact_flash']??null;unset($_SESSION['member_contact_flash']);
if($_SERVER['REQUEST_METHOD']==='POST'){
    $token=(string)($_POST['csrf_token']??'');if(!hash_equals($csrf,$token)){$_SESSION['member_contact_flash']=['type'=>'danger','message'=>'Your form session expired.'];header('Location: '.BASE_URL.'member/contact.php');exit;}
    $recipientId=(int)($_POST['recipient_id']??0);$subject=trim((string)($_POST['subject']??''));$message=trim((string)($_POST['message']??''));$recipient=null;foreach($recipients as $r){if((int)$r['id']===$recipientId){$recipient=$r;break;}}
    $errors=[];if(!$recipient)$errors[]='Select a valid recipient.';if($subject===''||mb_strlen($subject)>180)$errors[]='Enter a subject of not more than 180 characters.';if(mb_strlen($message)<10||mb_strlen($message)>5000)$errors[]='Message must be between 10 and 5,000 characters.';
    if(!$errors){
        $sender=mp_row($conn,'SELECT m.member_no,CONCAT(COALESCE(m.first_name,\'\'),\' \',COALESCE(m.last_name,\'\')) full_name,COALESCE(NULLIF(m.email,\'\'),u.email) email,COALESCE(NULLIF(m.phone,\'\'),u.phone) phone FROM members m JOIN users u ON u.id=m.user_id WHERE m.id=? AND u.id=? LIMIT 1','ii',[$mid,$uid])??[];
        $sent=false;$sendError='';$autoloads=[__DIR__.'/../vendor/autoload.php',__DIR__.'/../../vendor/autoload.php'];foreach($autoloads as $a){if(is_file($a)){require_once $a;break;}}
        $body="A member sent a message through the church portal.\n\nMember: ".($sender['full_name']??'Member')."\nMember No: ".($sender['member_no']??'-')."\nEmail: ".($sender['email']??'-')."\nPhone: ".($sender['phone']??'-')."\n\nMessage:\n".$message;
        try{
            if(class_exists(\PHPMailer\PHPMailer\PHPMailer::class)){$mail=new \PHPMailer\PHPMailer\PHPMailer(true);$mail->isMail();$mail->CharSet='UTF-8';$from=(string)($sender['email']??'');if(!filter_var($from,FILTER_VALIDATE_EMAIL))$from='no-reply@'.($_SERVER['HTTP_HOST']??'localhost');$mail->setFrom($from,(string)($sender['full_name']??'Church Member'));$mail->addAddress((string)$recipient['email'],(string)$recipient['full_name']);$mail->Subject='Member Portal: '.$subject;$mail->Body=$body;$mail->send();$sent=true;}else{$headers='Content-Type: text/plain; charset=UTF-8' . "\r\n"; $sent=mail((string)$recipient['email'],'Member Portal: '.$subject,$body,$headers);}
        }catch(Throwable $e){$sendError=$e->getMessage();error_log('[Member Contact] '.$sendError);}
        if(mp_table($conn,'member_messages')){try{$status=$sent?'sent':'failed';$st=$conn->prepare('INSERT INTO member_messages(member_id,user_id,recipient_user_id,recipient_role,subject,message,status,error_message,sent_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$role=(string)$recipient['role'];$errorText=$sendError;$st->bind_param('iiisssss',$mid,$uid,$recipientId,$role,$subject,$message,$status,$errorText);$st->execute();$st->close();}catch(Throwable $e){error_log('[Member Contact Log] '.$e->getMessage());}}
        $_SESSION['member_contact_flash']=$sent?['type'=>'success','message'=>'Your email was sent successfully to '.$allowedRoles[$recipient['role']].'.']:['type'=>'danger','message'=>'The email could not be sent. Please confirm the server mail settings.'];
    }else $_SESSION['member_contact_flash']=['type'=>'danger','message'=>implode(' ',$errors)];
    header('Location: '.BASE_URL.'member/contact.php');exit;
}
$sentRows=mp_table($conn,'member_messages')?mp_rows($conn,'SELECT subject,recipient_role,status,sent_at FROM member_messages WHERE member_id=? ORDER BY sent_at DESC LIMIT 10','i',[$mid]):[];
include __DIR__.'/../includes/sidebar.php';?><div class="main-content"><?php include __DIR__.'/../includes/topbar.php';?><div class="content-wrapper"><?php if(is_array($flash)):?><div class="alert alert-<?=mp_h($flash['type'])?>"><?=mp_h($flash['message'])?></div><?php endif;?><div class="member-stats"><div class="member-stat"><span><i class="fas fa-user-shield"></i></span><div><small>Available Recipients</small><strong><?=count($recipients)?></strong></div></div><div class="member-stat"><span><i class="fas fa-paper-plane"></i></span><div><small>Recent Messages</small><strong><?=count($sentRows)?></strong></div></div><div class="member-stat"><span><i class="fas fa-envelope-circle-check"></i></span><div><small>Sent Successfully</small><strong><?=count(array_filter($sentRows,fn($r)=>($r['status']??'')==='sent'))?></strong></div></div></div><div class="contact-grid"><div class="card"><div class="card-header"><h3>Send Email to Church Office</h3></div><div class="card-body"><form method="post"><input type="hidden" name="csrf_token" value="<?=mp_h($csrf)?>"><div class="form-group"><label>Send to</label><select class="form-control" name="recipient_id" required><option value="">Select recipient</option><?php foreach($recipients as $r):?><option value="<?=(int)$r['id']?>"><?=mp_h($allowedRoles[$r['role']].' — '.($r['full_name']?:$r['email']))?></option><?php endforeach;?></select></div><div class="form-group"><label>Subject</label><input class="form-control" name="subject" maxlength="180" required></div><div class="form-group"><label>Message</label><textarea class="form-control" name="message" rows="9" maxlength="5000" required></textarea><small>Do not include passwords or highly sensitive information.</small></div><button class="btn btn-primary"><i class="fas fa-paper-plane"></i> Send Email</button></form></div></div><div class="card"><div class="card-header"><h3>Recent Messages</h3></div><div class="card-body"><?php mp_render_table($sentRows,['recipient_role'=>'Recipient','sent_at'=>'Sent On']);?></div></div></div></div></div></div><style>.contact-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);gap:18px}.form-group{margin-bottom:16px}.form-group label{display:block;margin-bottom:6px;font-weight:700}.form-group small{display:block;margin-top:5px;color:#6b7280}@media(max-width:900px){.contact-grid{grid-template-columns:1fr}}</style><?php mp_standard_styles();require_once __DIR__.'/../includes/footer.php';?>
